    assert_eq!(h.err(s("q", json!({"GroupId": ""}))), "InvalidParameterValue");
    assert_eq!(h.err(s("q", json!({"DeduplicationId": "x".repeat(129)}))), "InvalidParameterValue");
    assert_eq!(h.err(s("q", json!({"GroupId": "g"}))), "UnsupportedOperation");
    assert_eq!(h.err(s("q", json!({"DeduplicationId": "d"}))), "UnsupportedOperation");
    assert_eq!(h.err(s("f.fifo", json!({"DelaySeconds": 0, "GroupId": "g"}))), "UnsupportedOperation");
